        }
        jdbc.update("INSERT INTO pool_nested (sheet_id, pool_name, member_pool, share, listed, from_date, to_date) "
                + "SELECT ?, pool_name, member_pool, share, listed, from_date, to_date FROM pool_nested WHERE sheet_id = ?",
                to, from);

