-- The sheet each cloned sheet was cloned from: its source, whose rates it uses when it and its parents have none in
-- force for a grade on a date. Not dated, like the parent.
CREATE TABLE sheet_source (
    id        VARCHAR(255) PRIMARY KEY,
    source_id VARCHAR(255) NOT NULL
);
EOF
python3 - <<'EOF'
p='java/net/officefloor/hq/app/sheet/SheetClones.java'
s=open(p).read()
s=s.replace('''        jdbc.update("MERGE INTO sheet_loaded (id) KEY (id) VALUES (?)", to);
''','''        jdbc.update("MERGE INTO sheet_loaded (id) KEY (id) VALUES (?)", to);
        jdbc.update("INSERT INTO sheet_source (id, source_id) VALUES (?, ?)", to, from);
''',1)
open(p,'w').write(s)
p='java/net/officefloor/hq/app/rate/Rates.java'
s=open(p).read()
old=s[s.index('    /** The sheet, then its parent'):s.index('    /**\n     * Sets the rate')]
new='''    /**
     * The sheet, then its parent, its parent's parent and so on, up to {@link #PARENT_LEVELS} levels up; then, for a
     * sheet that was cloned, the lineage of the sheet it was cloned from (its parents and its own source in turn).
     */
    public List<String> lineage(String sheetId) {
        List<String> lineage = new java.util.ArrayList<>();
        String from = sheetId;
        while (from != null && !lineage.contains(from)) {
            lineage.add(from);
            String at = from;
            for (int level = 0; level < PARENT_LEVELS; level++) {
                // The parent is not dated: it is the one named now, even while the store is read as of a date.
                List<String> parent = jdbc.queryForList("SELECT setting_value FROM setting WHERE sheet_id = ? AND setting_key = ?",
                        String.class, at, Settings.PARENT);
                if (parent.isEmpty() || parent.get(0) == null || parent.get(0).isEmpty() || lineage.contains(parent.get(0))) {
                    break;
                }
                at = parent.get(0);
                lineage.add(at);
            }
            // The source is not dated either.
            List<String> source = jdbc.queryForList("SELECT source_id FROM sheet_source WHERE id = ?", String.class, from);
            from = source.isEmpty() ? null : source.get(0);
        }
        return lineage;
    }

'''
s=s.replace(old,new)
s=s.replace("up to {@link #PARENT_LEVELS} levels up.\n     */\n    public BigDecimal on(","up to {@link #PARENT_LEVELS} levels up,\n     * then the rate of the sheet it was cloned from (see {@link #lineage}).\n     */\n    public BigDecimal on(")
open(p,'w').write(s)
EOF
